import{_ as a,o,c as t,a2 as s}from"./chunks/framework.BfWdyVj4.js";const c=JSON.parse('{"title":"Radio, sounds and audio","description":"","frontmatter":{},"headers":[],"relativePath":"features/audio.md","filePath":"features/audio.md","lastUpdated":1793093713000}'),i={name:"features/audio.md"};function n(d,e,r,l,h,p){return o(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="radio-sounds-and-audio" tabindex="-1">Radio, sounds and audio <a class="header-anchor" href="#radio-sounds-and-audio" aria-label="Permalink to &quot;Radio, sounds and audio&quot;">​</a></h1><p><code>play_audio</code> and <code>stop_audio</code> play a sound, song or radio stream from an <strong>https</strong> link on the displays: the one that asked, one by name, or all of them. It goes out like an announcement, so a scheduled job can do it too.</p><p>The server checks the link really is audio first. While it plays, the display shows 🎵 with the title and a ⏹ button, uses its own volume (turned down while someone talks to it), and stays quiet at night unless <code>at_night</code> is set.</p><p>Anything on the server can play audio as well:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:8790/local/announce</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;audio&quot;: &quot;https://example.com/birdsong.mp3&quot;, &quot;title&quot;: &quot;Birdsong&quot;, &quot;to&quot;: &quot;Kitchen&quot;}&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:8790/local/announce</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;stop_audio&quot;: true}&#39;</span></span></code></pre></div><h2 id="radio" tabindex="-1">Radio <a class="header-anchor" href="#radio" aria-label="Permalink to &quot;Radio&quot;">​</a></h2><p>&quot;Play Radio 1&quot;, &quot;put on some jazz&quot;: <code>play_radio</code> finds a station by name or genre on <a href="https://www.radio-browser.info" target="_blank" rel="noreferrer">radio-browser.info</a>, a free, open directory of internet radio, and plays it like <code>play_audio</code>. <code>country</code> (a two-letter code such as <code>GB</code>) prefers that country&#39;s stations.</p><p>The displays&#39; page is https, so a station that&#39;s only http is tried over https first and, if it doesn&#39;t answer there, relayed through the Frog Hub server (<code>/api/radio/&lt;id&gt;</code>, only ever for a station <code>play_radio</code> chose). HLS stations, such as the BBC&#39;s, play through <a href="https://github.com/video-dev/hls.js" target="_blank" rel="noreferrer">hls.js</a>, which the display only loads when it needs it.</p><h2 id="sound-clips" tabindex="-1">Sound clips <a class="header-anchor" href="#sound-clips" aria-label="Permalink to &quot;Sound clips&quot;">​</a></h2><p>&quot;What does a humpback whale sound like?&quot;: <code>find_sound</code> searches <a href="https://commons.wikimedia.org" target="_blank" rel="noreferrer">Wikimedia Commons</a> and, with an API key, <a href="https://freesound.org" target="_blank" rel="noreferrer">Freesound</a> at the same time, and lists clips with their length, credit and licence. The assistant picks the one that fits and plays it with <code>play_audio</code>, credit and all. Commons&#39; many one-word pronunciation recordings are left out.</p><p>Commons needs no key. For Freesound, make a free account, apply for an API key at <a href="https://freesound.org/apiv2/apply" target="_blank" rel="noreferrer">freesound.org/apiv2/apply</a> and give it to setup (it&#39;s kept in <code>~/.config/froghub/freesound.key</code>; <code>FROGHUB_FREESOUND_KEY</code> overrides it).</p><p>Audio, radio and sound clips are all off with the grown-ups&#39; &quot;Play music&quot; switch.</p><p>To play music by name on a speaker in the room (an Echo or a Music Assistant speaker), see <a href="/features/devices-music#music-by-name">Room devices and music</a>.</p>`,13)])])}const k=a(i,[["render",n]]);export{c as __pageData,k as default};
